t cp=m[2];const ville=m[1].trim();texte=rue.includes(cp)?rue:`${rue}, ${cp} ${ville}`}texte=texte.split(/\s+/).filter(Boolean).join(" ");return texte||null}function porteUnNumero(adresse){const sansCp=String(adresse||"").replace(/\b\d{5}\b/g," ");return/\b\d{1,4}\s*(bis|ter|[a-d])?\b/i.test(sansCp)}function departement(adresse){const cps=String(adresse||"").match(/\b\d{5}\b/g);return cps?cps[cps.length-1].slice(0,2):null}function sensDossier(adresseDepart,adresseArrivee){const d=departement(adresseDepart);const a=departement(adresseArrivee);if(DEPTS_IDF.includes(a)&&!DEPTS_IDF.includes(d))return"aller";if(DEPTS_IDF.includes(d)&&!DEPTS_IDF.includes(a))return"retour";return null}function stockeAuDepot(mission,lieu){const texte=sansAccents(JSON.stringify(lieu||{}));if(texte.includes("saint-loubes")||texte.includes("saint loubes"))return true;return Boolean((mission||{}).garde_meuble)&&texte.includes("loubes")}function batirDossier(lead,page,lignes,souci){const manques=[];const contact=enteteContact(lead.description);let fiche=null;let proprietes={};let source=null;if(page&&lignes&&lignes.length){fiche=parserCorps(lignes);proprietes=page.properties||{};const[nomT,prenomT]=nomPrenomTitre(valeurPropriete(proprietes["Nom client"])||"");fiche.client.nom=fiche.client.nom||nomT;fiche.client.prenom=fiche.client.prenom||prenomT;completerParProprietes(fiche,proprietes);fiche.mission.date_chargement=valeurPropriete(proprietes["Date de chargement"]);source="notion"}if(!fiche){if(souci)manques.push(souci);const corps=corpsDuLead(lead.description);if(corps.length>5){fiche=parserCorps(corps);source="nocrm";manques.push("dossier lu dans la description noCRM, pas dans Notion")}else{fiche={client:{},mission:{},depart:{},arrivee:{},notes:[],alertes:[]};source="aucune";manques.push("ni fiche Notion ni corps exploitable dans noCRM")}}const client=fiche.client||{};const mission=fiche.mission||{};const depart=fiche.depart||{};const arrivee=fiche.arrivee||{};const nom=contact.nom||client.nom|