const etape = $('Réglages · WF1').first().json.etapeNocrm;
const leads = $('noCRM – opportunités de l’axe').all().map((i) => i.json).filter((l) => l && l.id);
// Dossiers ciblés : ceux que la page a demandés, lus un par un (absent si import habituel).
let cibles = [];
try { cibles = $('noCRM – dossiers ciblés').all().map((i) => i.json).filter((l) => l && l.id); } catch (e) { cibles = []; }

// Leçon noCRM : un filtre accepté puis ignoré rend 200 avec TOUTE la base.
const horsColonne = leads.filter((l) => l.step_id !== undefined && l.step_id !== null && Number(l.step_id) !== Number(etape));
if (horsColonne.length) {
  throw new Error('Le filtre ?step= de noCRM n’a pas filtré (' + horsColonne.length + ' dossiers hors colonne) — import interrompu.');
}

// Gagnés et devis en attente (`statutsImportes`) : la page sépare les deux avec la colonne `devis`.
const statuts = $('Réglages · WF1').first().json.statutsImportes || ['won'];
const gagnees = leads.filter((l) => statuts.includes(l.status));
// Un dossier ciblé est pris quel que soit son statut (devis en attente compris), une seule fois.
const deja = new Set(gagnees.map((l) => String(l.id)));
for (const l of cibles) if (!deja.has(String(l.id))) { gagnees.push(l); deja.add(String(l.id)); }
return gagnees.map((lead) => ({ json: {
  lead: { id: lead.id, title: lead.title, amount: lead.amount, description: lead.description, statut: lead.status },
  motRecherche: (motsDuNom(lead.title).sort((a, b) => b.length - a.length)[0]) || null,
