const tournees = $('Table – toutes les tournées').all().map((i) => i.json).filter((r) => r && r.id);
const arrets = $('Table – tous les arrêts').all().map((i) => i.json).filter((r) => r && r.id);
const envois = $('Table – journal des envois (état)').all().map((i) => i.json).filter((r) => r && r.id)
  .map(({ corps, ...reste }) => reste);  // le corps est dans la table ; la page n'en a pas besoin ici
// L'utilisateur connecté vient de l'authentification Basic : on ne le devine pas, on le lit.
const entete = $('Webhook · état').first().json.headers.authorization || '';
let qui = '';
try {
  qui = entete.startsWith('Basic ') ? Buffer.from(entete.slice(6), 'base64').toString('utf8').split(':')[0] : '';
} catch (e) { qui = ''; }
const r = $('Réglages · WF2').first().json;
const qualite = Object.fromEntries($('Table – journal qualité (état)').all().map((i) => i.json).filter((l) => l && l.id && l.messageId)
  .map((l) => [l.messageId, { verdict: l.verdict_humain || '', categorieCorrigee: l.categorie_corrigee || '' }]));
const flotte = $('Table – flotte (état)').all().map((i) => i.json).filter((r) => r && r.id && r.cle);
// Les 60 derniers relevés suffisent : la page n'en lit que le plus récent par offre.
const releves = $('Table – locations relevées (état)').all().map((i) => i.json).filter((r) => r && r.id && r.offre)
  .sort((a, b) => String(b.releveLe).localeCompare(String(a.releveLe))).slice(0, 60);
// Camions pris jour par jour d'après l'agenda de l'équipe : la page ne reçoit que ce résumé.
const lus = $('Google Agenda – missions de l’équipe').all().map((i) => i.json || {});
const panne = lus.find((e) => e.error && !e.id);
const agenda = panne
  ? { jours: {}, erreur: String((panne.error && panne.error.message) || panne.error).slice(0, 200) }
  : { jours: camionsPrisParJour(lus.filter((e) => e.id), flotte), erreur: '' };
return [{ json: { tournees, arrets, envois, qualite, qui, liens: { notion: r.lienFicheNotion, nocrm: r.lienFicheNocrm }, importAutoMinutes: r.importAutoMinutes,
  flotte, releves, offresLocation: r.offresLocation, lienLocation: r.lienLocation, tarifsRentabilite: r.tarifsRentabilite, agenda,
  validation: { depot: r.depotFiche, rapport: r.rapport } } }];

