const demandes = $('Voie concordante ?').all().map((i) => i.json);
const osm = $('OpenStreetMap – recherche').all().map((i) => i.json);
const communes = $input.all().map((i) => i.json);
const maintenant = new Date().toISOString();

const points = demandes.map((d, i) => {
  let retenu = d.retenu;

  if (!retenu) {
    const reponse = osm[i];
    const r = Array.isArray(reponse) ? reponse[0] : reponse;
    const libelle = r ? String(r.display_name || "") : "";
    if (r && r.lat && voieConcorde(d.voie, libelle)) {
      retenu = { libelle, lat: Number(r.lat), lon: Number(r.lon),
        precision: r.category === "place" ? "municipality" : "street",
        source: "osm", voieVerifiee: Boolean(d.voie) };
    }
  }

  if (!retenu) {
    // Dernier recours : le centre de la commune. Le point est faux de quelques centaines
    // de mètres, mais la tournée reste calculable — et le verdict le dira.
    const trait = (((communes[i] || {}).features) || [])[0];
    if (trait) {
      retenu = { libelle: trait.properties.label, lat: trait.geometry.coordinates[1],
        lon: trait.geometry.coordinates[0], precision: "municipality",
        source: "commune", voieVerifiee: false };
    }
  }

  const point = retenu ? { ...retenu, voieSaisie: Boolean(d.voie), numeroSaisi: d.numero } : null;
  const qualite = qualiteAdresse(point);
  return { adresse: d.adresse, cle: d.cle, sentinelle: Boolean(d.sentinelle),
    point: point ? { ...point, qualite } : null, qualite };
});

return [{ json: { points, maintenant } }];

const { points, maintenant } = $input.first().json;
