const connus = $('Table – géocodages connus').all().map((i) => i.json).filter((r) => r && r.cle);
const trouves = $('Points retenus').first().json.points.filter((p) => p.point);

const parCle = new Map();
for (const c of connus) parCle.set(c.cle, { lat: c.lat, lon: c.lon });
for (const p of trouves) parCle.set(p.cle, { lat: p.point.lat, lon: p.point.lon });

// On ne réécrit que ce qui a bougé : une écriture inutile est une écriture qui peut se perdre.
const aEcrire = [];
for (const a of arrets) {
  const p = parCle.get(cleAdresse(a.adresse));
  if (!p || (a.lat === p.lat && a.lon === p.lon)) continue;
  aEcrire.push({ json: { id: a.id, lat: p.lat, lon: p.lon } });
}
return aEcrire.length ? aEcrire : [{ json: { aucun: true } }];

