const reglages = $('Réglages · WF3').first().json;
const arrets = $('Table – arrêts à situer').all().map((i) => i.json).filter((r) => r && r.id);
const connus = $('Table – géocodages connus').all().map((i) => i.json).filter((r) => r && r.cle);
const trouves = $('Points retenus').first().json.points.filter((p) => p.point);

const parCle = new Map();
for (const c of connus) parCle.set(c.cle, { lat: c.lat, lon: c.lon, qualite: c.qualite, libelle: c.libelle });
for (const p of trouves) parCle.set(p.cle, { lat: p.point.lat, lon: p.point.lon, qualite: p.qualite, libelle: p.point.libelle });

const situe = (adresse) => parCle.get(cleAdresse(adresse)) || null;
const ancre = (adresse, role) => {
  const p = situe(adresse);
  return { role, adresse, region: regionDuPoint(p, adresse), lat: p ? p.lat : null, lon: p ? p.lon : null,
    qualite: p ? p.qualite : "introuvable", libelle: p ? p.libelle : null };
};

// Les points, ancres comprises : une demi-tournée part de l’une et finit à l’autre.
const points = [
  ancre(reglages.depot, "depot"),
  ancre(reglages.porteNordGironde, "porte-gironde"),
  ancre(reglages.porteSudIdf, "porte-idf"),
];
for (const a of arrets) {
  const p = situe(a.adresse);
  points.push({ role: "arret", id: a.id, type: a.type, client: a.client, leadId: a.leadId,
    adresse: a.adresse, region: regionDuPoint(p, a.adresse), lat: p ? p.lat : null, lon: p ? p.lon : null,
    qualite: p ? p.qualite : "introuvable", libelle: p ? p.libelle : null });
}

const parRegion = { gironde: [], idf: [] };
points.forEach((p, i) => { if (p.region && p.lat !== null) parRegion[p.region].push(i); });

const demandes = [];
for (const nom of ['gironde', 'idf']) {
  const indices = parRegion[nom];
  if (indices.length < 2) continue;
  const lieux = indices.map((i) => ({ lat: points[i].lat, lon: points[i].lon }));
  demandes.push({ json: { matrice: nom, indices, points,
    jsonValhalla: JSON.stringify({ sources: lieux, targets: lieux, costing: "truck", units: "kilometers" }) } });
}

// La liaison entre régions passe par le service d’itinéraire : Valhalla refuse plus de
// 150 km dans une matrice (error_code 154) — constaté le 23/09/2026, la matrice « axe »
// échouait à chaque calcul.
const g = points.findIndex((p) => p.role === "porte-gironde" && p.lat !== null);
const i2 = points.findIndex((p) => p.role === "porte-idf" && p.lat !== null);
if (g >= 0 && i2 >= 0) {
  // Les deux variantes : la page applique la règle maison (sans péage tant que
  // l’aller-retour tient sous 19 h 06 — outils/itineraire/calcul_itineraire.py).
  for (const [nom, peage] of [["axe", 0], ["axePeage", 1]]) {
    demandes.push({ json: { matrice: nom, service: "route", indices: [g, i2], points,
      jsonValhalla: JSON.stringify({ locations: [{ lat: points[g].lat, lon: points[g].lon },
        { lat: points[i2].lat, lon: points[i2].lon }], costing: "truck",
        costing_options: { truck: { use_tolls: peage } }, units: "kilometers",
        directions_type: "none" }) } });
  }
}

return demandes.length ? demandes : [{ json: { matrice: "aucune", indices: [], points, jsonValhalla: "" } }];

const demandes = $('Matrices à demander').all().map((i) => i.json);
const reponses = $input.all().map((i) => i.json);
const points = demandes[0] ? demandes[0].points || [] : [];

// Valhalla rend les durées en secondes et les distances en kilomètres, couple par couple.
const matrices = {};
demandes.forEach((d, i) => {
  if (!d.indices || d.indices.length < 2) return;
  const r = reponses[i] || {};
  // Itinéraire simple (l’axe) : une durée dans chaque sens, supposée symétrique.
  const resume = r.trip && r.trip.summary;
  const brut = resume
    ? [[{ time: 0, distance: 0 }, { time: resume.time, distance: resume.length }],
      [{ time: resume.time, distance: resume.length }, { time: 0, distance: 0 }]]
    : (r.sources_to_targets || []);
  matrices[d.matrice] = {
    indices: d.indices,
    h: brut.map((ligne) => ligne.map((c) => Math.round((((c || {}).time) || 0) / 3600 * 10000) / 10000)),
    km: brut.map((ligne) => ligne.map((c) => Math.round((((c || {}).distance) || 0) * 100) / 100)),
    erreur: r.error || (resume || brut.length ? null : "réponse vide"),
  };
});

const lus = $('Points retenus').first().json.points.filter((p) => !p.sentinelle);
return [{ json: { points, matrices, geocodages: lus } }];

// Réglages du bloc WF4 — rien de configurable ailleurs dans le canevas.
const REGLAGES = {
  "mode": "simulation",
  "expediteur": "karimbordeau@samdemenage.fr",
  "alias": ""
};

const w = $('Webhook · mails').first().json;
const corps = w.body || {};
const entete = (w.headers || {}).authorization || '';
let qui = '';
try { qui = entete.startsWith('Basic ') ? Buffer.from(entete.slice(6), 'base64').toString('utf8').split(':')[0] : ''; } catch (e) { qui = ''; }
const leads = Array.isArray(corps.leads) && corps.leads.length ? corps.leads.map(String) : null;
// Textes retouchés dans la page : { leadId: { objet, corps } }. Le destinataire, lui, ne vient jamais de la page.
const textes = corps.textes && typeof corps.textes === 'object' ? corps.textes : {};
