const plat = (s) => String(s || '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;| /g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
const sortie = [];
demandes.forEach((a, i) => {
  const reponse = lus[i] || {};
  const corps = reponse.body;
  const liste = Array.isArray(corps) ? corps : (corps && (corps.data || corps.comments)) || [];
  const deja = liste.some((c) => plat(c.content).includes(plat(a.texte)));
  sortie.push({ json: { action: a, deja, erreurLecture: reponse.error ? String(reponse.error.message || reponse.error) : '' } });
});
const aPoser = sortie.filter((s) => !s.json.deja && !s.json.erreurLecture);
return aPoser.length ? aPoser : [{ json: { aucun: true } }];

const e = $('Écritures prévues').first().json;
const R = $('Réglages · WF7').first().json;
const a = e.actions.find((x) => x.cible === 'rapport' && (x.operation === 'creer' || x.operation === 'remplacer'));
return a ? [{ json: { action: a, ancien: a.idExterne || 'aucun', a: R.rapportA, objet: a.objet, html: a.html } }] : [{ json: { aucun: true } }];

const e = $('Écritures prévues').first().json;
const maintenant = new Date().toISOString();
const sorties = (nom) => { try { return $(nom).all().map((i) => i.json); } catch (err) { return null; } };
const erreurDe = (r) => (r && r.error ? String(r.error.message || r.error.description || r.error).slice(0, 300) : '');
const lignes = [];
const bilan = { crees: 0, modifies: 0, annules: 0, commentes: 0, rapport: '', erreurs: [] };
const ligne = (a, champs) => lignes.push({ cle: a.cle, mode: e.mode, tournee: e.tournee, cible: a.cible, leadId: a.leadId || '',
  titre: a.titre || '', empreinte: a.empreinte || '', majLe: maintenant, majPar: e.qui, erreur: '', ...champs });

const creees = sorties('Google Agenda – création');
if (creees) {
  $('Événements à créer').all().map((i) => i.json).forEach((d, i) => {
    if (d.aucun) return;
    const r = creees[i] || {};
    if (r.id) { bilan.crees += 1; ligne(d.action, { idExterne: r.id, etat: 'actif' }); }
    else { bilan.erreurs.push(d.action.titre + ' : ' + (erreurDe(r) || 'création refusée')); ligne(d.action, { idExterne: '', etat: 'erreur', erreur: erreurDe(r), empreinte: '' }); }
  });
}
const envoyees = sorties('Google Agenda – mise à jour');
if (envoyees) {
  $('Modifications à envoyer').all().map((i) => i.json).forEach((d, i) => {
    const r = envoyees[i] || {};
    const a = d.action;
    if (d.introuvable) {
      // Supprimé à la main dans l'agenda : la prochaine validation le recréera.
      bilan.erreurs.push(a.titre + ' : introuvable dans l’agenda — il sera recréé à la prochaine validation');
      return ligne(a, { idExterne: '', etat: 'perdu', empreinte: '' });
    }
    if (r.id) {
      if (a.operation === 'annuler') { bilan.annules += 1; ligne(a, { idExterne: a.idExterne, etat: 'annule' }); }
      else { bilan.modifies += 1; ligne(a, { idExterne: a.idExterne, etat: 'actif' }); }
    } else { bilan.erreurs.push(a.titre + ' : ' + (erreurDe(r) || 'mise à jour refusée')); }
  });
}
// noCRM, dossier par dossier : erreur de lecture (rien n'est rangé, on réessaiera), déjà présent
// (rangé sans être reposé), ou posé.
const demandesNocrm = sorties('Commentaires noCRM') || [];
const lusNocrm = sorties('noCRM – commentaires existants');
const aPoserNocrm = (sorties('Commentaires à poser') || []).filter((d) => !d.aucun);
const poses = sorties('noCRM – nouveau commentaire') || [];
if (lusNocrm) {
  demandesNocrm.forEach((d, i) => {
    if (d.aucun) return;
    const lu = lusNocrm[i] || {};
    if (erreurDe(lu)) { bilan.erreurs.push('noCRM ' + d.action.leadId + ' (lecture) : ' + erreurDe(lu)); return; }
    const j = aPoserNocrm.findIndex((p) => p.action.cle === d.action.cle);
    if (j < 0) { ligne(d.action, { idExterne: '', etat: 'actif' }); return; }
    const r = poses[j] || {};
    if (erreurDe(r)) bilan.erreurs.push('noCRM ' + d.action.leadId + ' : ' + erreurDe(r));
    else { bilan.commentes += 1; ligne(d.action, { idExterne: String(r.id || ''), etat: 'actif' }); }
  });
}
const brouillon = sorties('Gmail – brouillon du rapport');
if (brouillon && brouillon[0]) {
  const d = $('Rapport à poser').first().json;
  const r = brouillon[0];
  if (r.id) { bilan.rapport = d.action.operation === 'remplacer' ? 'remplacé' : 'posé'; ligne(d.action, { idExterne: r.id, etat: 'actif', titre: d.objet }); }
  else bilan.erreurs.push('Rapport gérant : ' + (erreurDe(r) || 'brouillon refusé'));
}
return lignes.length ? lignes.map((l) => ({ json: l })).concat([]) : [{ json: { aucun: true } }];

const e = $('Écritures prévues').first().json;
const lignes = $('Journal de la synchro').all().map((i) => i.json).filter((l) => !l.aucun);
const compte = (f) => lignes.filter(f).length;
const crees = compte((l) => l.cible.startsWith('agenda') && l.etat === 'actif' && e.actions.some((a) => a.cle === l.cle && a.operation === 'creer'));
const modifies = compte((l) => l.cible.startsWith('agenda') && l.etat === 'actif' && e.actions.some((a) => a.cle === l.cle && a.operation === 'mettre_a_jour'));
const annules = compte((l) => l.etat === 'annule');
const commentes = compte((l) => l.cible === 'nocrm' && l.etat === 'actif');
const rapport = lignes.find((l) => l.cible === 'rapport' && l.etat === 'actif');
const erreurs = lignes.filter((l) => l.etat === 'erreur' || l.etat === 'perdu').map((l) => l.titre + (l.erreur ? ' : ' + l.erreur : ' : introuvable, recréé à la prochaine validation'));
const ou = e.mode === 'reel' ? 'l’agenda de l’équipe' : 'l’agenda « ZZ test groupage »';
const morceaux = [
  crees ? crees + ' événement(s) créé(s)' : null, modifies ? modifies + ' mis à jour' : null, annules ? annules + ' marqué(s) « ANNULÉ »' : null,
].filter(Boolean);
const message = (e.mode === 'test' ? 'Mode test — ' : '') + (morceaux.length ? morceaux.join(', ') + ' dans ' + ou : 'Agenda déjà à jour')
  + (commentes ? ' · ' + commentes + ' commentaire(s) noCRM' : '') + (rapport ? ' · rapport gérant en brouillon' : '')
  + (erreurs.length ? ' · ' + erreurs.length + ' échec(s) : ' + erreurs.join(' ; ') : '') + '.';
return [{ json: { mode: e.mode, ecrit: true, message, erreurs, resume: e.resume } }];

// Réglages du bloc WF1 — rien de configurable ailleurs dans le canevas.
const REGLAGES = {
  "etapeNocrm": 730698,
  "statutsImportes": [
    "won",
    "standby",
    "todo"
  ],
  "nocrmBase": "https://samdemenage.nocrm.io/api/v2",
  "notionBase": "https://api.notion.com/v1",
  "notionBaseFiches": "80ce1be8-ba79-4a07-88df-ae8c88eb0ab7",
  "notionVersion": "2022-06-28",
  "mode": "reel",
  "maxDossiersCibles": 20
};

// Import ciblé : la page envoie { groupage, leadIds } quand une tournée est créée depuis la carte.
// La nuit et le lancement manuel n’ont pas de corps : import habituel seulement.
let corps = {};
try { corps = $('Webhook · import depuis la page').first().json.body || {}; } catch (e) { corps = {}; }
const cibleLeads = (Array.isArray(corps.leadIds) ? corps.leadIds : []).map(String).filter((id) => /^[0-9]{1,12}$/.test(id))
  .slice(0, REGLAGES.maxDossiersCibles);
const cibleGroupage = typeof corps.groupage === 'string' ? corps.groupage.slice(0, 120) : '';
return [{ json: { ...REGLAGES, cibleLeads: cibleGroupage ? cibleLeads : [], cibleGroupage } }];

const r = $('Réglages · WF1').first().json;
const ids = r.cibleLeads || [];
// Aucun dossier ciblé : un item témoin, sinon la chaîne s'arrêterait ici (LECONS).
return ids.length ? ids.map((id) => ({ json: { id } })) : [{ json: { aucun: true } }];

