const tournees = $('Table – toutes les tournées').all().map((i) => i.json).filter((r) => r && r.id);
const arrets = $('Table – tous les arrêts').all().map((i) => i.json).filter((r) => r && r.id);
const envois = $('Table – journal des envois (état)').all().map((i) => i.json).filter((r) => r && r.id)
  .map(({ corps, ...reste }) => reste);  // le corps est dans la table ; la page n'en a pas besoin ici
// L'utilisateur connecté vient de l'authentification Basic : on ne le devine pas, on le lit.
const entete = $('Webhook · état').first().json.headers.authorization || '';
let qui = '';
try {
  qui = entete.startsWith('Basic ') ? Buffer.from(entete.slice(6), 'base64').toString('utf8').split(':')[0] : '';
} catch (e) { qui = ''; }
const r = $('Réglages · WF2').first().json;
const qualite = Object.fromEntries($('Table – journal qualité (état)').all().map((i) => i.json).filter((l) => l && l.id && l.messageId)
  .map((l) => [l.messageId, { verdict: l.verdict_humain || '', categorieCorrigee: l.categorie_corrigee || '' }]));
const flotte = $('Table – flotte (état)').all().map((i) => i.json).filter((r) => r && r.id && r.cle);
